  } else if(e.key === 'Backspace' && tagInput.value === '' && pendingTags.length){
    pendingTags.pop(); renderPendingTags();
  }
});
tagInput.addEventListener('blur', () => {
  if(tagInput.value.trim()){ addPendingTag(tagInput.value); tagInput.value=''; }
});

render();

