shown.forEach(it => {
  const div = document.createElement('div');
  div.className = 'item' + (it.toread ? '' : ' read');
  div.setAttribute('data-item', it.id);

  if(editingId === it.id){
    div.innerHTML =
      '<div class="edit-field"><label>Title</label>' +
        '<input type="text" id="e-title" value="'+ (it.title||'').replace(/"/g,'&quot;') +'"></div>' +
      '<div class="edit-field"><label>Why are you saving this?</label>' +
        '<textarea id="e-note">'+ (it.note||'') +'</textarea></div>' +
      '<div class="edit-field"><label>Tags (comma-separated)</label>' +
        '<input type="text" id="e-tags" value="'+ (it.tags||[]).join(', ') +'"></div>' +
      '<div class="actions">' +
        '<button class="primary" id="e-save" style="color:#fff">Save changes</button> ' +
        '<button id="e-cancel">Cancel</button></div>';
    listEl.appendChild(div);
    div.querySelector('#e-save').addEventListener('click', () => {
      const t = div.querySelector('#e-title').value.trim();
      const n = div.querySelector('#e-note').value.trim();
      const tags = div.querySelector('#e-tags').value.split(',')
        .map(s => s.trim().replace(/^#/,'').toLowerCase()).filter(Boolean);
      const target = items.find(x => x.id === it.id);
      if(target){ target.title = t; target.note = n; target.tags = Array.from(new Set(tags)); }
      editingId = null; render();
    });
    div.querySelector('#e-cancel').addEventListener('click', () => { editingId = null; render(); });
    return;
  }

  const title = it.title || it.url;
  let tagsHtml = '';
  if((it.tags||[]).length){
    tagsHtml = '<div class="tags">' + it.tags.map(t =>
      '<span class="tag click" data-tag="'+t+'">#'+t+'</span>').join('') + '</div>';
  }
  const badge = it.toread ? '<span class="badge toread">To read</span>' : '';
  const copyBadge = it.keepcopy ? '<span class="badge copy">Copy kept</span>' : '';
  const copyBtn = it.keepcopy ? ' <button data-copy="'+it.id+'">View saved copy</button>' : '';
  div.innerHTML =
    '<a class="title" href="'+it.url+'" target="_blank" rel="noopener">'+title+'</a>' + badge + copyBadge +
    '<div class="host">'+hostOf(it.url)+'</div>' +
    (it.note ? '<div class="note">'+it.note+'</div>' : '') +
    tagsHtml +
    '<div class="actions"><button data-edit="'+it.id+'">Edit</button> '+
      '<button data-toggle="'+it.id+'">'+
      (it.toread ? 'Mark as read' : 'Mark as to read')+'</button>'+copyBtn+'</div>';
  div.querySelectorAll('.tags .tag').forEach(el => {
    el.addEventListener('click', () => { activeFilter = el.dataset.tag; render(); });
  });
  div.querySelector('[data-edit]').addEventListener('click', () => { editingId = it.id; render(); });
  div.querySelector('[data-toggle]').addEventListener('click', () => {
    const target = items.find(x => x.id === it.id);
    if(target){ target.toread = !target.toread; render(); }
  });
  const cb = div.querySelector('[data-copy]');
  if(cb) cb.addEventListener('click', () => showSavedCopy(it));
  listEl.appendChild(div);
});

