  '<div id="e-msg" style="margin-top:8px;font-size:13px;"></div>' +
  '<div class="actions">' +
    '<button class="primary" id="e-save" style="color:#fff">Save changes</button> ' +
    '<button id="e-cancel">Cancel</button></div>';
listEl.appendChild(div);
div.querySelector('#e-save').addEventListener('click', () => {
  const emsg = div.querySelector('#e-msg');
  emsg.innerHTML = '';
  const newUrl = normUrl(div.querySelector('#e-url').value);
  if(!isValidUrl(newUrl)){
    emsg.innerHTML = '<div class="msg-error">That doesn\'t look like a valid web address.</div>';
    return;
  }
  const clash = items.find(x => x.id !== it.id &&
    x.url.replace(/\/+$/,'') === newUrl.replace(/\/+$/,''));
  if(clash){
    emsg.innerHTML = '<div class="msg-error">Another saved link already uses that address ('+
      (clash.title||clash.url)+').</div>';
    return;
  }
  const t = div.querySelector('#e-title').value.trim();
  const n = div.querySelector('#e-note').value.trim();
  const tags = div.querySelector('#e-tags').value.split(',')
    .map(s => s.trim().replace(/^#/,'').toLowerCase()).filter(Boolean);
  const target = items.find(x => x.id === it.id);
  if(target){ target.url = newUrl; target.title = t; target.note = n; target.tags = Array.from(new Set(tags)); }
  editingId = null; render();
});

